def lines(buf: io.StringIO) -> list[dict[str, Any]]:
    return [json.loads(line) for line in buf.getvalue().splitlines() if line.strip()]


def memory_connector(exporter: InMemoryLogExporter, closed: list[int]) -> sdk.LogConnector:
    def connect(resource: Any, _env: Any, on_dropped: Any) -> sdk.LogConnection:
        options = sdk.BatchOptions(on_drop=lambda records, _reason: on_dropped(records))
        logs = sdk.BatchingLogClient(exporter, resource=resource, options=options)

        def close() -> None:
            closed.append(1)
            logs.close()

        return sdk.LogConnection(logs=logs, close=close)

    return connect


def test_stdout_only() -> None:
    buf = io.StringIO()
    log = sdk.init_logging(
        env={"GROW_SERVICE_NAME": "orders", "GROW_ENVIRONMENT": "dev", "LOG_LEVEL": "debug"},
        stream=buf,
    )
    assert sdk.logging_client() is None
    token = sdk.request_id_var.set("req-1")
    try:
        log.debug("hello", extra={"password": "p", "n": 1})
    finally:
        sdk.request_id_var.reset(token)
    try:
        raise ValueError("boom")
    except ValueError:
        logging.getLogger("x").exception("failed")
    out = lines(buf)
    assert out[0]["level"] == "debug" and out[0]["msg"] == "hello"
    assert out[0]["service"] == "orders" and out[0]["environment"] == "dev"
    assert out[0]["password"] == "[REDACTED]" and out[0]["n"] == 1
    assert out[0]["request_id"] == "req-1" and "log_shipped" not in out[0]
    assert "ValueError" in out[1]["exception"]
    assert not sdk.send_canary("c")
    sdk.flush_logging()


def test_ships_and_canary() -> None:
    exporter = InMemoryLogExporter()
    closed: list[int] = []
    buf = io.StringIO()
    sdk.init_logging(
        "svc",
        "info",
        env={"GROW_LOGGING_PROVIDER": sdk.PACKAGE_KEY},
        stream=buf,
        connect=memory_connector(exporter, closed),
    )
    provider = TracerProvider()
    with provider.get_tracer("t").start_as_current_span("s"):
        token = sdk.request_id_var.set("r")
        logging.getLogger("app").info("shipped", extra={"token": "t"})
        sdk.request_id_var.reset(token)
    assert sdk.send_canary("foundation-canary-1", {"foundation.trigger": "health"})
    sdk.flush_logging()
    out = lines(buf)
    assert out[0]["log_shipped"] == "sdk" and out[0]["token"] == "[REDACTED]"
    assert len(out[0]["trace_id"]) == 32
    bodies = [r.body for r in exporter.records]
    assert bodies == ["shipped", "foundation-canary-1"]
    assert exporter.records[0].attributes["request_id"] == "r"
    assert exporter.records[0].resource["service.name"] == "svc"
    sdk.shutdown_logging()
    sdk.shutdown_logging()
    assert closed == [1]
    _ = trace


def test_failed_exports_are_reemitted() -> None:
    exporter = InMemoryLogExporter()
    exporter.fail_next(5, RuntimeError("down"))
    buf = io.StringIO()
    sdk.init_logging(
        "svc",
        ship=True,
        env={"GROW_ENVIRONMENT": "dev"},
        stream=buf,
        connect=memory_connector(exporter, []),
    )
    provider = TracerProvider()
    with provider.get_tracer("t").start_as_current_span("s"):
        logging.getLogger("app").warning("lost", extra={"password": "p"})
    sdk.flush_logging()
    out = lines(buf)
    assert out[0]["log_shipped"] == "sdk"
    failed = [line for line in out if line.get("log_shipped") == "sdk_failed"]
    assert failed and failed[0]["msg"] == "lost" and failed[0]["password"] == "[REDACTED]"
    assert failed[0]["service"] == "svc" and failed[0]["environment"] == "dev"
    assert len(failed[0]["trace_id"]) == 32


