def test_asgi_middleware() -> None:
    buf = io.StringIO()
    sdk.init_logging(env={}, stream=buf)
    seen: list[str | None] = []

    async def app(scope: Any, receive: Any, send: Any) -> None:
        seen.append(sdk.request_id_var.get())
        if scope["type"] == "http":
            status = 404 if scope["path"] == "/missing" else 200
            await send({"type": "http.response.start", "status": status, "headers": []})
            await send({"type": "http.response.body", "body": b""})

    sent: list[Any] = []

    async def send(message: Any) -> None:
        sent.append(message)

    async def receive() -> Any:
        return {}

    mw = sdk.RequestLoggingMiddleware(app)

    async def run() -> None:
        await mw(
            {
                "type": "http",
                "path": "/missing",
                "method": "GET",
                "headers": [(b"x-request-id", b"abc")],
            },
            receive,
            send,
        )
        await mw({"type": "http", "path": "/health/live", "headers": []}, receive, send)
        await mw({"type": "lifespan"}, receive, send)

    asyncio.run(run())
    assert seen[0] == "abc" and seen[1] not in (None, "abc") and seen[2] is None
    assert (b"x-request-id", b"abc") in sent[0]["headers"]
    out = [line for line in lines(buf) if line["msg"] == "request completed"]
    assert len(out) == 1
    assert out[0]["level"] == "warn" and out[0]["http.status_code"] == 404
    assert out[0]["request_id"] == "abc"


def test_wsgi_middleware() -> None:
    buf = io.StringIO()
    sdk.init_logging(env={}, stream=buf)

    def app(environ: Any, start_response: Any) -> list[bytes]:
        start_response("503 Service Unavailable", [])
        return [str(sdk.request_id_var.get()).encode()]

    headers: list[Any] = []
    mw = sdk.RequestLoggingWSGIMiddleware(app)
    body = mw(
        {"PATH_INFO": "/x", "REQUEST_METHOD": "POST", "HTTP_X_REQUEST_ID": "w1"},
        lambda status, h, *a: headers.append(h),
    )
    assert list(body) == [b"w1"] and ("X-Request-Id", "w1") in headers[0]
    mw({"PATH_INFO": "/health/ready"}, lambda status, h, *a: None)
    out = [line for line in lines(buf) if line["msg"] == "request completed"]
    assert len(out) == 1 and out[0]["level"] == "error" and out[0]["http.method"] == "POST"
